1	package netproxy
2	
3	import (
4		"net/url"
5		"os"
6		"slices"
7		"strings"
8		"sync"
9	)
10	
11	// ForwardedVariables are the variables a container receives, in this order,
12	// each name followed by its other casing. ALL_PROXY and FTP_PROXY are not read.
13	var ForwardedVariables = []string{
14		"HTTP_PROXY", "http_proxy",
15		"HTTPS_PROXY", "https_proxy",
16		"NO_PROXY", "no_proxy",
17	}
18	
19	// redacted stands for a proxy value that could not be parsed, so it has no
20	// display form.
21	const redacted = "[redacted]"
22	
23	// forwardPair is one variable in both casings, with the value they both carry.
24	type forwardPair struct {
25		names [2]string
26		value string
27		// read is the name the value was read from, with the case it had.
28		read string
29	}
30	
31	// Forward is a snapshot of the proxy variables as a child process must receive
32	// them. It holds raw values, credentials included, and never prints them: String
33	// and GoString show the display form. A Forward kept in an unexported field is
34	// walked by fmt, which cannot call String there, so the values sit behind a
35	// function: fmt prints an address for it, with every verb (a pointer to a struct
36	// would be followed by %s). The zero value forwards nothing.
37	type Forward struct {
38		get func() []forwardPair
39	}
40	
41	// pairs returns the variables held, none for the zero value.
42	func (f Forward) pairs() []forwardPair {
43		if f.get == nil {
44			return nil
45		}
46		return f.get()
47	}
48	
49	// containerForward reads the environment once, like http.ProxyFromEnvironment.
50	var containerForward = sync.OnceValue(func() Forward {
51		return ForwardFromLookup(os.LookupEnv)
52	})
53	
54	// ContainerForward is the proxy environment of this process, read once.
55	func ContainerForward() Forward { return containerForward() }
56	
57	// ForwardFromLookup reads the variables through lookup. For each of HTTP, HTTPS
58	// and NO, the first non-empty value of the upper case name then the lower case
59	// name is given to both names. The value is not validated.
60	func ForwardFromLookup(lookup func(string) (string, bool)) Forward {
61		getenv := func(name string) string {
62			v, _ := lookup(name)
63			return v
64		}
65		var pairs []forwardPair
66		for i := 0; i < len(ForwardedVariables); i += 2 {
67			names := [2]string{ForwardedVariables[i], ForwardedVariables[i+1]}
68			if read, value := firstNonEmpty(names, getenv); read != "" {
69				pairs = append(pairs, forwardPair{names: names, value: value, read: read})
70			}
71		}
72		if len(pairs) == 0 {
73			return Forward{}
74		}
75		return Forward{get: func() []forwardPair { return pairs }}
76	}
77	
78	// Empty reports whether there is nothing to forward.
79	func (f Forward) Empty() bool { return len(f.pairs()) == 0 }
80	
81	// Names lists the variables to pass, in ForwardedVariables order.
82	func (f Forward) Names() []string {
83		var names []string
84		for _, p := range f.pairs() {
85			names = append(names, p.names[:]...)
86		}
87		return names
88	}
89	
90	// Environ returns base without any of the six forwarded names, followed by
91	// NAME=value for every name to forward. base is not modified; when there is
92	// nothing to forward it is returned as is.
93	func (f Forward) Environ(base []string) []string {
94		if f.Empty() {
95			return base
96		}
97		env := make([]string, 0, len(base)+len(f.pairs())*2)
98		for _, kv := range base {
99			name, _, _ := strings.Cut(kv, "=")
100			if !slices.Contains(ForwardedVariables, name) {
101				env = append(env, kv)
102			}
103		}
104		for _, p := range f.pairs() {
105			for _, name := range p.names {
106				env = append(env, name+"="+p.value)
107			}
108		}
109		return env
110	}
111	
112	// Loopback reports whether a proxy the container would use is on this machine,
113	// where it cannot be reached from inside the container. The HTTPS pair is tried
114	// before the HTTP pair and the first loopback value wins. variable is the name
115	// that was read and display carries no credential.
116	func (f Forward) Loopback() (variable, display string, ok bool) {
117		for _, upper := range []string{"HTTPS_PROXY", "HTTP_PROXY"} {
118			for _, p := range f.pairs() {
119				if p.names[0] != upper {
120					continue
121				}
122				if u, usable := parseProxyValue(p.value); usable && isLoopbackHost(u.Hostname()) {
123					return p.read, Display(u), true
124				}
125			}
126		}
127		return "", "", false
128	}
129	
130	// Redact removes every credential held by f from s: a raw proxy value becomes
131	// its display form (or [redacted] when it is unusable), and its userinfo and
132	// its password disappear, as written in the value, as Go escapes them and
133	// decoded. For an unusable value holding "@", everything before the last "@"
134	// is taken for a userinfo. A secret shorter than 4 bytes is only removed in the
135	// full value and in user:password@, since replacing it anywhere would damage
136	// the text; a bare user name shorter than 4 bytes is not removed at all.
137	func (f Forward) Redact(s string) string {
138		var r redaction
139		for _, p := range f.pairs() {
140			if p.names[0] != "NO_PROXY" {
141				r.addValue(p.value)
142			}
143		}
144		return r.apply(s)
145	}
146	
147	// redaction collects what Redact removes. strings.Replacer tries its arguments
148	// in order at each position, so apply lists the longest kinds first.
149	type redaction struct {
150		values    [][2]string // raw value and what stands for it
151		userinfos []string    // removed together with their "@"
152		secrets   []string    // replaced wherever they appear
153	}
154	
155	// addValue records one raw proxy value and the credentials it holds.
156	func (r *redaction) addValue(value string) {
157		display := redacted
158		u, usable := parseProxyValue(value)
159		if usable {
160			display = Display(u)
161			if u.User != nil {
162				r.addUserinfo(u.User.String())
163			}
164		}
165		r.values = append(r.values, [2]string{value, display})
166		rest := value[len(explicitScheme.FindString(value)):]
167		if usable {
168			// The authority ends at the first "/", "?" or "#".
169			if end := strings.IndexAny(rest, "/?#"); end >= 0 {
170				rest = rest[:end]
171			}
172		}
173		// Written out, whatever the escaping: up to the last "@".
174		if at := strings.LastIndex(rest, "@"); at >= 0 {
175			r.addUserinfo(rest[:at])
176		}
177	}
178	
179	// addUserinfo records a userinfo as written, user[:password], and its decoded
180	// form. The secret is the password, or the user name when the password is
181	// absent or empty.
182	func (r *redaction) addUserinfo(info string) {
183		user, password, _ := strings.Cut(info, ":")
184		secret := password
185		if secret == "" {
186			secret = user
187		}
188		for _, v := range unescapedToo(info) {
189			// A bare short name would match the local part of an address.
190			if v != "" && (strings.Contains(v, ":") || len(v) >= 4) {
191				r.userinfos = append(r.userinfos, v)
192			}
193		}
194		for _, v := range unescapedToo(secret) {
195			if len(v) >= 4 {
196				r.secrets = append(r.secrets, v)
197			}
198		}
199	}
200	
201	// unescapedToo returns s and, when it differs and decodes, its percent-decoded form.
202	func unescapedToo(s string) []string {
203		if d, err := url.PathUnescape(s); err == nil && d != s {
204			return []string{s, d}
205		}
206		return []string{s}
207	}
208	
209	// apply performs the replacements on s.
210	func (r *redaction) apply(s string) string {
211		var olds []string
212		byLength := func(a, b string) int { return len(b) - len(a) }
213		slices.SortStableFunc(r.values, func(a, b [2]string) int { return byLength(a[0], b[0]) })
214		for _, v := range r.values {
215			olds = append(olds, v[0], v[1])
216		}
217		slices.SortStableFunc(r.userinfos, byLength)
218		for _, info := range slices.Compact(r.userinfos) {
219			olds = append(olds, info+"@", "")
220		}
221		slices.SortStableFunc(r.secrets, byLength)
222		for _, secret := range slices.Compact(r.secrets) {
223			olds = append(olds, secret, redacted)
224		}
225		if len(olds) == 0 {
226			return s
227		}
228		return strings.NewReplacer(olds...).Replace(s)
229	}
230	
231	// String shows the variables with the proxies in display form, never raw. A
232	// NO_PROXY value with a non-printable character is not shown, since it ends up
233	// on a terminal.
234	func (f Forward) String() string {
235		if f.Empty() {
236			return "no proxy variables"
237		}
238		parts := make([]string, 0, len(f.pairs()))
239		for _, p := range f.pairs() {
240			shown := redacted
241			if p.names[0] == "NO_PROXY" {
242				if isPrintable(p.value) {
243					shown = p.value
244				}
245			} else if u, ok := parseProxyValue(p.value); ok {
246				shown = Display(u)
247			}
248			parts = append(parts, p.names[0]+"="+shown)
249		}
250		return strings.Join(parts, " ")
251	}
252	
253	// GoString is String, so %#v shows no raw value either.
254	func (f Forward) GoString() string { return f.String() }
255

